  const e = strictDiag('duplicate-key', line, `重复键 "${key}"`);
  e.firstLine = firstLine;
  e.key = key;
  return e;
}

function stripComment(line) {
  let inS = false, inD = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
